style:
.tc-grain-widget { padding: 12px 16px; }
.tc-grain-widget-title { font-size: var(--text-lg, 14px); font-weight: 600; color: var(--text-color); margin-bottom: 8px; }
.tc-grain-widget-sub { font-weight: 400; color: var(--text-muted); font-size: var(--text-sm, 12px); }
.tc-grain-widget-empty { color: var(--text-muted); font-size: var(--text-sm, 12px); padding: 24px 0; text-align: center; }
.tc-heatmap-table { border-collapse: collapse; width: 100%; font-size: var(--text-sm, 12px); }
.tc-heatmap-table th, .tc-heatmap-table td { padding: 6px 10px; text-align: center; border: 1px solid var(--border-color); }
.tc-heatmap-table th { background: var(--subtle-fg); font-weight: 600; text-transform: capitalize; }
.tc-heatmap-grain { text-align: left; font-weight: 500; white-space: nowrap; }
.tc-heatmap-note { color: var(--text-muted); font-size: var(--text-sm, 12px); margin-top: 8px; }

script:
(function () {
	function esc(s) {
		return frappe.utils.escape_html(String(s == null ? "" : s));
	}

	function render(matrix) {
		var sources = matrix.sources || [];
		var rows = matrix.rows || [];
		var host = root_element.querySelector("#tc-heatmap");
		var emptyEl = root_element.querySelector(".tc-grain-widget-empty");
		var noteEl = root_element.querySelector(".tc-heatmap-note");
		if (!rows.length) {
			emptyEl.style.display = "block";
			return;
		}
		var max = 1;
		rows.forEach(function (r) {
			sources.forEach(function (s) { max = Math.max(max, r[s] || 0); });
		});
		var html = '<table class="tc-heatmap-table"><thead><tr><th>Grain</th>';
		sources.forEach(function (s) { html += "<th>" + esc(s) + "</th>"; });
		html += "</tr></thead><tbody>";
		rows.forEach(function (r) {
			html += '<tr><td class="tc-heatmap-grain">' + esc(r.grain) + "</td>";
			sources.forEach(function (s) {
				var v = r[s] || 0;
				var pct = v ? (12 + 78 * (v / max)) : 4;
				html += '<td class="tc-heatmap-cell" style="background-color: color-mix(in srgb, var(--blue-500) ' + pct.toFixed(0) + '%, transparent);" title="' + esc(s) + ": " + v + '">' + v + "</td>";
			});
			html += "</tr>";
		});
		html += "</tbody></table>";
		host.innerHTML = html;
		if (!matrix.error_log_readable) {
			noteEl.style.display = "block";
		}
	}

	frappe.call({
		method: "tatva_connect.automation.report.grain_log_matrix",
		args: { days: 7 },
		callback: function (r) { render(r.message || { sources: [], rows: [] }); }
	});
})();
